properties.query:
let _NetskopeEmpty = datatable(TimeGenerated:datetime, action_s:string, category_s:string, severity_s:string, malware_name_s:string, malware_type_s:string, threat_name_s:string, user_s:string, domain_s:string, dstip_s:string, srcip_s:string, bytes_uploaded_d:real, bytes_downloaded_d:real, app_s:string, url_s:string, dlp_rule_s:string, dlp_profile_s:string, activity_s:string, file_type_s:string, object_s:string)[];
let baselineWindow = 7d;
let recentWindow   = 4h;
let minBaselineReqsPerDay = 20;
let BaselineUsers =
    union isfuzzy=true _NetskopeEmpty, NetskopeWebTx_CL
    | where TimeGenerated between (ago(baselineWindow) .. ago(recentWindow))
    | where isnotempty(user_s)
    | summarize
        BaselineReqPerDay = round(toreal(count()) / (baselineWindow / 1d), 1),
        BaselineApps           = make_set(app_s, 10),
        BaselineIPs            = make_set(srcip_s, 5)
      by user_s
    | where BaselineReqPerDay >= minBaselineReqsPerDay;
let RecentActiveUsers =
    union isfuzzy=true _NetskopeEmpty, NetskopeWebTx_CL
    | where TimeGenerated > ago(recentWindow)
    | where isnotempty(user_s)
    | distinct user_s;
BaselineUsers
| join kind=leftanti RecentActiveUsers on user_s
| project
    user_s, BaselineReqPerDay, BaselineApps, BaselineIPs
| order by BaselineReqPerDay desc

let _NetskopeEmpty = datatable(TimeGenerated:datetime, action_s:string, category_s:string, severity_s:string, malware_name_s:string, malware_type_s:string, threat_name_s:string, user_s:string, domain_s:string, dstip_s:string, srcip_s:string, bytes_uploaded_d:real, bytes_downloaded_d:real, app_s:string, url_s:string, dlp_rule_s:string, dlp_profile_s:string, activity_s:string, file_type_s:string, object_s:string)[];
let TI_IOCs = ThreatIntelIndicators | where TimeGenerated > ago(30d) | where isempty(ValidUntil) or ValidUntil > now() | where (isnotnull(parse_ipv4(ObservableValue)) or ObservableKey has "domain") | where isnotempty(ObservableValue) | summarize TI_ThreatTypes = make_set(Tags), TI_Confidence = max(Confidence) by IOC_Value = ObservableValue;
union isfuzzy=true _NetskopeEmpty, NetskopeWebTx_CL | where TimeGenerated > ago(24h) | where action_s !in ("block", "Block", "blocked", "Blocked") | where isnotempty(domain_s) or isnotempty(dstip_s) | extend MatchKey = coalesce(domain_s, tostring(dstip_s)) | summarize RequestCount = count(), UniqueUsers = dcount(user_s), UserList = make_set(user_s, 10) by MatchKey, domain_s, dstip_s | join kind=inner TI_IOCs on $left.MatchKey == $right.IOC_Value | order by TI_Confidence desc, RequestCount desc

let _NetskopeEmpty = datatable(TimeGenerated:datetime, action_s:string, category_s:string, severity_s:string, malware_name_s:string, malware_type_s:string, threat_name_s:string, user_s:string, domain_s:string, dstip_s:string, srcip_s:string, bytes_uploaded_d:real, bytes_downloaded_d:real, app_s:string, url_s:string, dlp_rule_s:string, dlp_profile_s:string, activity_s:string, file_type_s:string, object_s:string)[];
let baselineWindow = 7d; let recentWindow = 4h; let minBaselineReqsPerDay = 20;
let BaselineUsers = union isfuzzy=true _NetskopeEmpty, NetskopeWebTx_CL | where TimeGenerated between (ago(baselineWindow) .. ago(recentWindow)) | where isnotempty(user_s) | summarize BaselineRequestsPerDay = round(toreal(count()) / (baselineWindow / 1d), 1), BaselineApps = make_set(app_s, 10), BaselineIPs = make_set(srcip_s, 5) by user_s | where BaselineRequestsPerDay >= minBaselineReqsPerDay;
let RecentActiveUsers = union isfuzzy=true _NetskopeEmpty, NetskopeWebTx_CL | where TimeGenerated > ago(recentWindow) | where isnotempty(user_s) | distinct user_s;
BaselineUsers | join kind=leftanti RecentActiveUsers on user_s | order by BaselineRequestsPerDay desc

let _NetskopeEmpty = datatable(TimeGenerated:datetime, action_s:string, category_s:string, severity_s:string, malware_name_s:string, malware_type_s:string, threat_name_s:string, user_s:string, domain_s:string, dstip_s:string, srcip_s:string, bytes_uploaded_d:real, bytes_downloaded_d:real, app_s:string, url_s:string, dlp_rule_s:string, dlp_profile_s:string, activity_s:string, file_type_s:string, object_s:string)[];
let NetskopeBlocks = union isfuzzy=true _NetskopeEmpty, NetskopeWebTx_CL | where TimeGenerated > ago(24h) | where action_s in ("block", "Block", "blocked", "Blocked") | where category_s has_any ("Malware", "Phishing", "Botnet", "Command and Control", "Ransomware") or isnotempty(malware_name_s) | summarize NK_BlockCount = count(), NK_DestDomains = make_set(domain_s, 10), NK_Categories = make_set(category_s, 5), NK_Users = make_set(user_s, 5) by NK_SrcIP = srcip_s;
SecurityAlert | where TimeGenerated > ago(24h) | where AlertSeverity in ("High", "Medium") | mv-expand todynamic(Entities) | extend EntityIP = tostring(Entities.Address) | where isnotempty(EntityIP) | summarize Alert_Count = count(), Alert_Names = make_set(AlertName, 5), Alert_Products = make_set(ProductName, 5) by EntityIP
| join kind=inner NetskopeBlocks on $left.EntityIP == $right.NK_SrcIP
| order by NK_BlockCount desc, Alert_Count desc

let _NetskopeEmpty = datatable(TimeGenerated:datetime, action_s:string, category_s:string, severity_s:string, malware_name_s:string, malware_type_s:string, threat_name_s:string, user_s:string, domain_s:string, dstip_s:string, srcip_s:string, bytes_uploaded_d:real, bytes_downloaded_d:real, app_s:string, url_s:string, dlp_rule_s:string, dlp_profile_s:string, activity_s:string, file_type_s:string, object_s:string)[];
let HuntWindow = 7d; let ExfilCategories = dynamic(["Cloud Storage", "File Sharing", "Online Storage and Backup", "Personal Sites & Blogs", "Webmail", "Social Networking"]);
let Daily = union isfuzzy=true _NetskopeEmpty, NetskopeWebTx_CL | where TimeGenerated > ago(HuntWindow) | where action_s !in ("block", "Block") | where isnotempty(user_s) | where category_s in (ExfilCategories) or activity_s == "Upload" | summarize DaySentBytes = sum(todouble(bytes_uploaded_d)), DayRequestCount = count() by user_s, Day = bin(TimeGenerated, 1d);
let Users = Daily | summarize TotalMBSent = round(toreal(sum(DaySentBytes)) / 1048576, 2), ActiveDays = dcount(Day), TotalRequests = sum(DayRequestCount) by user_s;
let globalAvg = toscalar(Users | summarize avg(TotalMBSent)); let globalStd = toscalar(Users | summarize stdev(TotalMBSent));
Users | extend Zscore = iff(globalStd > 0, round((TotalMBSent - globalAvg) / globalStd, 2), 0.0) | where Zscore >= 2.5 or (ActiveDays >= 5 and TotalMBSent > 50) | order by Zscore desc
